/**
 * FORMAT presets for well-known math tests. These describe structure, timing, tools and scoring only —
 * public format facts from the test makers' own descriptions. No official questions are reproduced;
 * questions are generated by practice-engine or varied from the student's own uploads.
 *
 * In a preset, `Section.questionIds` are SLOTS, not questions: "sat-m1-01:mc:1" = slot 1 of module 1,
 * question type mc, worth 1 point. buildExam fills each slot with a real question. Slot type "qc" is a
 * GRE-style quantitative comparison (an 'mc' question with the four fixed comparison choices).
 *
 * All score conversions are ESTIMATES: real conversions are equated per test form and not public in a
 * form we could reproduce, so the UI labels them "-style" and "(estimate)".
 */
import type { Topic } from '@lemma/practice-engine';
import type { ExamProfile, QuestionType, ScoringScale, Section } from './types';

export type PresetId = 'sat-style' | 'psat-style' | 'act-style' | 'ap-style' | 'gre-style' | 'ib-style' | 'class';
export type SlotType = QuestionType | 'qc';

export interface SlotSpec {
  type: SlotType;
  points: number;
}

/** "sat-m1-01:mc:1" → { type: 'mc', points: 1 }; null for ids that aren't slots. */
export function parseSlot(id: string): SlotSpec | null {
  const m = /:(mc|qc|multi|numeric|expression|short|free)(?::(\d+(?:\.\d+)?))?$/.exec(id);
  return m ? { type: m[1] as SlotType, points: m[2] ? Number(m[2]) : 1 } : null;
}

function slots(prefix: string, plan: [SlotType, number, number][]): string[] {
  const out: string[] = [];
  for (const [type, count, points] of plan) for (let i = 0; i < count; i++) out.push(`${prefix}-${String(out.length + 1).padStart(2, '0')}:${type}:${points}`);
  return out;
}

/** Interleaves types evenly through a section (minority types spread out, not bunched at the end). */
function spread(prefix: string, plan: [SlotType, number, number][]): string[] {
  const total = plan.reduce((s, p) => s + p[1], 0);
  const placed = plan.map(() => 0);
  const out: string[] = [];
  for (let i = 0; i < total; i++) {
    let best = 0;
    let debt = -Infinity;
    plan.forEach(([, count], k) => {
      if (placed[k]! >= count) return;
      const d = ((i + 1) * count) / total - placed[k]!;
      if (d > debt + 1e-12) [best, debt] = [k, d];
    });
    placed[best]!++;
    const [type, , points] = plan[best]!;
    out.push(`${prefix}-${String(i + 1).padStart(2, '0')}:${type}:${points}`);
  }
  return out;
}

const LETTER_BANDS: NonNullable<ScoringScale['bands']> = [
  { minPercent: 93, label: 'A' },
  { minPercent: 90, label: 'A-' },
  { minPercent: 87, label: 'B+' },
  { minPercent: 83, label: 'B' },
  { minPercent: 80, label: 'B-' },
  { minPercent: 77, label: 'C+' },
  { minPercent: 73, label: 'C' },
  { minPercent: 70, label: 'C-' },
  { minPercent: 67, label: 'D+' },
  { minPercent: 63, label: 'D' },
  { minPercent: 60, label: 'D-' },
  { minPercent: 0, label: 'F' },
];
export const letterBands = () => LETTER_BANDS.map((b) => ({ ...b }));

type W = [Topic, number, string[]?];
const topics = (list: W[]): ExamProfile['topics'] => list.map(([topic, weight, subtopics]) => (subtopics ? { topic, weight, subtopics } : { topic, weight }));

const SAT_REFERENCE =
  'Reference: area of a circle A = πr², circumference C = 2πr; rectangle A = lw; triangle A = ½bh; Pythagorean theorem c² = a² + b²; ' +
  'special right triangles 30°-60°-90° (x, x√3, 2x) and 45°-45°-90° (s, s, s√2); volumes: box V = lwh, cylinder V = πr²h, sphere V = 4/3πr³, ' +
  'cone V = 1/3πr²h, pyramid V = 1/3lwh. A circle has 360° (2π radians); the angles of a triangle sum to 180°.';

/*
 * Digital SAT Math (College Board, digital SAT since March 2024): two stage-adaptive modules of 22 questions,
 * 35 minutes each (70 min, 44 questions). Module 2 is easier or harder depending on module 1 performance.
 * About 75% four-option multiple choice and about 25% student-produced response (SPR). Calculator (built-in
 * Desmos graphing) allowed for the whole section; reference sheet available. Section score 200–800, no
 * guessing penalty. Each module includes 2 unscored pretest questions (not modelled separately).
 * Uncertain: the exact MC/SPR split per module varies by form — we use 17 MC + 5 SPR per module; routing
 * threshold is not published — 0.6 of module 1 is a stand-in.
 */
function digitalSat(id: 'sat-style' | 'psat-style'): ExamProfile {
  const p = id === 'sat-style' ? 'sat' : 'psat';
  const plan: [SlotType, number, number][] = [['mc', 17, 1], ['numeric', 5, 1]];
  const sections: Section[] = [
    { id: 'm1', title: 'Module 1', minutes: 35, calculator: true, questionIds: spread(`${p}-m1`, plan), canReturn: false, instructions: 'You may return to questions within this module until time runs out.' },
    {
      id: 'm2',
      title: 'Module 2',
      minutes: 35,
      calculator: true,
      questionIds: [],
      adaptive: { after: 'm1', threshold: 0.6, easy: spread(`${p}-m2e`, plan), hard: spread(`${p}-m2h`, plan) },
      canReturn: false,
      instructions: 'Module 2 is chosen from your Module 1 performance.',
    },
  ];
  return {
    id,
    name: id === 'sat-style' ? 'Digital SAT-style Math' : 'PSAT/NMSQT-style Math',
    family: id,
    room: 'digital-adaptive',
    sections,
    // PSAT/NMSQT Math section: 160–760 (PSAT 8/9 uses 120–720; not modelled).
    scoring: id === 'sat-style' ? { kind: 'scaled', min: 200, max: 800, guessingPenalty: 0 } : { kind: 'scaled', min: 160, max: 760, guessingPenalty: 0 },
    tools: { calculator: 'graphing', referenceSheet: SAT_REFERENCE, scratch: true, highlighter: true, eliminator: true, markForReview: true },
    rules: { fullscreen: true, warnAtMinutes: [5], allowPause: false, showTimer: 'toggle' },
    observations: [
      'Format follows the public digital SAT Math description: 2 adaptive modules × 22 questions × 35 minutes.',
      'About 75% four-choice multiple choice and 25% student-produced response; calculator allowed throughout.',
      'Scaled score and module-2 routing are estimates (real conversions are form-specific).',
    ],
    topics: topics([
      ['linear', 0.2, ['linear equations', 'linear functions']],
      ['system', 0.1, ['systems of equations']],
      ['quadratic', 0.15, ['nonlinear functions']],
      ['exponents', 0.1, ['equivalent expressions', 'exponential functions']],
      ['percent', 0.1, ['percentages', 'ratios and rates']],
      ['stats', 0.1, ['one-variable data', 'probability']],
      ['units', 0.05, ['units and rates']],
      ['geometry', 0.15, ['area and volume', 'right triangles']],
      ['fractions', 0.05],
    ]),
    mix: { mc: 34 / 44, numeric: 10 / 44 },
  };
}

/*
 * ACT Math, enhanced ACT (online from spring 2025, paper from September 2025): 45 questions in 50 minutes,
 * four answer choices. Scale 1–36, no guessing penalty; most graphing calculators permitted (CAS models
 * banned). Some questions are unscored field-test items (count not modelled). Earlier format: 60
 * questions / 60 minutes / five choices — available as ACT_LEGACY_VARIANT.
 */
function act(legacy = false): ExamProfile {
  const n = legacy ? 60 : 45;
  return {
    id: legacy ? 'act-style-legacy' : 'act-style',
    name: legacy ? 'ACT-style Math (pre-2025: 60 questions, 5 choices)' : 'ACT-style Math',
    family: 'act-style',
    room: 'digital-linear',
    sections: [{ id: 'math', title: 'Mathematics', minutes: legacy ? 60 : 50, calculator: true, questionIds: slots('act-math', [['mc', n, 1]]), canReturn: true }],
    scoring: { kind: 'scaled', min: 1, max: 36, guessingPenalty: 0 },
    tools: { calculator: 'graphing', scratch: true, highlighter: true, eliminator: true, markForReview: true },
    rules: { fullscreen: true, warnAtMinutes: [5], allowPause: false, showTimer: 'always' },
    observations: [
      legacy ? 'Older ACT Math format: 60 questions in 60 minutes, five answer choices.' : 'Enhanced ACT Math format: 45 questions in 50 minutes, four answer choices.',
      'Scale score 1–36 is an estimate.',
      `Answer choices per question: ${legacy ? 5 : 4}.`,
    ],
    topics: topics([
      ['arithmetic', 0.08, ['number and quantity']],
      ['fractions', 0.07],
      ['percent', 0.08],
      ['linear', 0.15, ['linear functions']],
      ['system', 0.07],
      ['quadratic', 0.13, ['polynomials']],
      ['exponents', 0.1, ['exponential functions']],
      ['geometry', 0.17, ['plane geometry', 'trigonometry']],
      ['stats', 0.1, ['statistics and probability']],
      ['units', 0.05],
    ]),
    mix: { mc: 1 },
  };
}

/*
 * AP Calculus AB (College Board Course and Exam Description): Section I multiple choice, 45 questions,
 * Part A 30 questions / 60 min no calculator, Part B 15 questions / 45 min graphing calculator required;
 * Section II free response, Part A 2 questions / 30 min calculator, Part B 4 questions / 60 min no
 * calculator. MC and FRQ each 50% of the score; four-choice MC (A–D); each FRQ is scored out of 9; no
 * guessing penalty. Composite here = 1.2 × MC + FRQ points (54 + 54), mapped to 1–5 with ILLUSTRATIVE
 * cutoffs — real cutoffs change every year. Since 2025 the MC section is taken in the Bluebook app while
 * FRQs are handwritten; we model the whole exam as a 'paper' room.
 */
function ap(): ExamProfile {
  return {
    id: 'ap-style',
    name: 'AP Calculus-style',
    family: 'ap-style',
    room: 'paper',
    sections: [
      { id: 's1a', title: 'Section I, Part A — Multiple choice, no calculator', minutes: 60, calculator: false, questionIds: slots('ap-1a', [['mc', 30, 1.2]]), canReturn: false },
      { id: 's1b', title: 'Section I, Part B — Multiple choice, calculator', minutes: 45, calculator: true, questionIds: slots('ap-1b', [['mc', 15, 1.2]]), canReturn: false, breakAfterMinutes: 10 },
      { id: 's2a', title: 'Section II, Part A — Free response, calculator', minutes: 30, calculator: true, questionIds: slots('ap-2a', [['free', 2, 9]]), canReturn: false },
      {
        id: 's2b',
        title: 'Section II, Part B — Free response, no calculator',
        minutes: 60,
        calculator: false,
        questionIds: slots('ap-2b', [['free', 4, 9]]),
        canReturn: true,
        // As on the real exam: during Part B you may go back to Part A's questions, without a calculator, on Part B's time.
        returnTo: { section: 's2a', calculator: false },
        instructions: 'No calculator in this part. You may also go back to Part A questions, without a calculator; time spent there comes out of Part B’s time.',
      },
    ],
    scoring: {
      kind: 'band',
      bands: [
        { minPercent: 58, label: '5' },
        { minPercent: 45, label: '4' },
        { minPercent: 33, label: '3' },
        { minPercent: 23, label: '2' },
        { minPercent: 0, label: '1' },
      ],
      guessingPenalty: 0,
    },
    tools: { calculator: 'graphing', scratch: true, highlighter: false, eliminator: true, markForReview: true },
    rules: { fullscreen: false, warnAtMinutes: [10, 5], allowPause: false, showTimer: 'always' },
    observations: [
      'Format follows the public AP Calculus AB exam description (Section I MC 45 Q, Section II FRQ 6 Q).',
      'Calculator only in Section I Part B and Section II Part A.',
      'During Section II Part B you may return to Part A questions, without a calculator, on Part B’s time.',
      'The 1–5 score is an estimate from illustrative cutoffs.',
    ],
    topics: topics([
      ['derivative', 0.6, ['limits', 'chain rule', 'product rule', 'tangent lines', 'related rates', 'optimization']],
      ['integral', 0.4, ['definite integrals', 'u-substitution', 'accumulation']],
    ]),
    mix: { mc: 45 / 51, free: 6 / 51 },
  };
}

/*
 * GRE General Test, Quantitative Reasoning (ETS, shorter test since September 2023): two sections,
 * 12 questions / 21 minutes then 15 questions / 26 minutes; section-level adaptive (section 2 difficulty
 * depends on section 1). Question types: quantitative comparison (four fixed choices), multiple choice
 * with one answer (five choices), multiple choice with one or more answers (no partial credit), numeric
 * entry. On-screen basic calculator. Score 130–170 in 1-point steps, no guessing penalty.
 * Uncertain: ETS doesn't publish a fixed type split; ours (≈ 35% QC, 40% MC, 10% multi, 15% numeric)
 * follows published practice tests.
 */
function gre(): ExamProfile {
  const s1: [SlotType, number, number][] = [['qc', 4, 1], ['mc', 5, 1], ['multi', 1, 1], ['numeric', 2, 1]];
  const s2: [SlotType, number, number][] = [['qc', 5, 1], ['mc', 6, 1], ['multi', 2, 1], ['numeric', 2, 1]];
  return {
    id: 'gre-style',
    name: 'GRE-style Quantitative Reasoning',
    family: 'gre-style',
    room: 'digital-adaptive',
    sections: [
      { id: 'q1', title: 'Quantitative Reasoning, Section 1', minutes: 21, calculator: true, questionIds: slots('gre-q1', s1), canReturn: false },
      {
        id: 'q2',
        title: 'Quantitative Reasoning, Section 2',
        minutes: 26,
        calculator: true,
        questionIds: [],
        adaptive: { after: 'q1', threshold: 0.6, easy: slots('gre-q2e', s2), hard: slots('gre-q2h', s2) },
        canReturn: false,
      },
    ],
    scoring: { kind: 'scaled', min: 130, max: 170, guessingPenalty: 0 },
    tools: { calculator: 'basic', scratch: true, highlighter: false, eliminator: false, markForReview: true },
    rules: { fullscreen: true, warnAtMinutes: [5], allowPause: false, showTimer: 'toggle' },
    observations: [
      'Format follows the public GRE General Test description (shorter test): 12 Q / 21 min, then an adaptive 15 Q / 26 min section.',
      'Quantitative comparison, single-answer MC (5 choices), select-all MC (no partial credit), numeric entry.',
      'The 130–170 score is an estimate.',
    ],
    topics: topics([
      ['arithmetic', 0.2, ['number properties']],
      ['fractions', 0.1],
      ['percent', 0.12],
      ['linear', 0.15],
      ['quadratic', 0.1],
      ['exponents', 0.08],
      ['geometry', 0.12],
      ['stats', 0.13, ['data analysis', 'probability']],
    ]),
    mix: { mc: 20 / 27, multi: 3 / 27, numeric: 4 / 27 },
  };
}

/*
 * IB Mathematics: Analysis and Approaches SL (syllabus first assessed 2021): Paper 1 no calculator and
 * Paper 2 graphing calculator, each 90 minutes and 80 marks, each with Section A (short response) and
 * Section B (extended response); formula booklet provided. HL adds longer papers and Paper 3 (not modelled).
 * Grades 1–7 from boundaries set each session — ours are rough estimates. Papers are sat in separate
 * sessions; the simulation runs them back to back. Uncertain: the number of Section A questions varies by
 * session (we use 6 short + 3 long per paper, 40 + 40 marks).
 */
function ib(): ExamProfile {
  const plan = (p: string): string[] => [...slots(`${p}a`, [['short', 2, 7], ['short', 1, 6], ['short', 1, 7], ['short', 2, 6.5]]), ...slots(`${p}b`, [['free', 1, 14], ['free', 2, 13]])];
  return {
    id: 'ib-style',
    name: 'IB Math AA SL-style',
    family: 'ib-style',
    room: 'paper',
    sections: [
      { id: 'p1', title: 'Paper 1 — No calculator', minutes: 90, calculator: false, questionIds: plan('ib-p1'), canReturn: false, instructions: 'Section A: short response. Section B: extended response. Full marks need working.' },
      { id: 'p2', title: 'Paper 2 — Graphing calculator', minutes: 90, calculator: true, questionIds: plan('ib-p2'), canReturn: false, instructions: 'Section A: short response. Section B: extended response.' },
    ],
    scoring: {
      kind: 'band',
      bands: [
        { minPercent: 71, label: '7' },
        { minPercent: 57, label: '6' },
        { minPercent: 44, label: '5' },
        { minPercent: 31, label: '4' },
        { minPercent: 19, label: '3' },
        { minPercent: 8, label: '2' },
        { minPercent: 0, label: '1' },
      ],
      guessingPenalty: 0,
    },
    tools: { calculator: 'graphing', formulaSheet: 'IB-style formula booklet (standard formulas: sequences, logarithms, quadratic formula, derivatives, integrals, statistics).', scratch: true, highlighter: false, eliminator: false, markForReview: false },
    rules: { fullscreen: false, warnAtMinutes: [10, 5], allowPause: false, showTimer: 'always' },
    observations: ['Format follows the public IB Math AA SL description: Paper 1 (no calculator) and Paper 2 (calculator), 90 min / 80 marks each.', 'The 1–7 grade is an estimate.'],
    topics: topics([
      ['quadratic', 0.15, ['functions']],
      ['exponents', 0.15, ['logarithms', 'exponential functions']],
      ['derivative', 0.2],
      ['integral', 0.15],
      ['stats', 0.15, ['probability']],
      ['geometry', 0.12, ['trigonometry']],
      ['arithmetic', 0.08, ['sequences']],
    ]),
    mix: { short: 12 / 18, free: 6 / 18 },
  };
}

/** A generic 50-minute class paper test: 20 four-choice MC (3 pts) + 5 free response (8 pts) = 100 pts. */
function classTest(): ExamProfile {
  return {
    id: 'class',
    name: 'Class test',
    family: 'class',
    room: 'paper',
    sections: [{ id: 'test', title: 'Test', minutes: 50, calculator: true, questionIds: [...slots('class-mc', [['mc', 20, 3]]), ...slots('class-fr', [['free', 5, 8]])], canReturn: true, instructions: 'Show all work on free response questions.' }],
    scoring: { kind: 'percent', bands: letterBands(), guessingPenalty: 0 },
    tools: { calculator: 'scientific', scratch: true, highlighter: false, eliminator: true, markForReview: true },
    rules: { fullscreen: false, warnAtMinutes: [10, 5], allowPause: false, showTimer: 'always' },
    observations: ['Generic class test: 50 minutes, 20 multiple choice (4 choices, 3 pts) and 5 free response (8 pts).', 'Answer choices per question: 4.'],
    topics: topics([
      ['linear', 0.25],
      ['quadratic', 0.2],
      ['exponents', 0.15],
      ['fractions', 0.1],
      ['percent', 0.1],
      ['system', 0.1],
      ['stats', 0.1],
    ]),
    mix: { mc: 0.8, free: 0.2 },
  };
}

export const PRESETS: Record<PresetId, ExamProfile> = {
  'sat-style': digitalSat('sat-style'),
  'psat-style': digitalSat('psat-style'),
  'act-style': act(),
  'ap-style': ap(),
  'gre-style': gre(),
  'ib-style': ib(),
  class: classTest(),
};

/** The pre-2025 ACT Math format (60 questions, 60 minutes, five choices). */
export const ACT_LEGACY_VARIANT: ExamProfile = act(true);

/** Rules per family that the profile shape doesn't carry. */
export interface FamilyRules {
  choices: number;
  /** Select-all questions earn partial credit. */
  multiPartial: boolean;
  /** SAT-style grid-in: decimals must fill the answer space (5 characters, 6 with a minus sign). */
  gridIn: boolean;
  /** Accept a correctly rounded decimal (≥ 2 places) for a non-terminating exact answer. */
  roundedOk: boolean;
  /** Number questions per section (digital) instead of continuously (paper). */
  numberPerSection: boolean;
}

export function familyRules(family: ExamProfile['family'], profile?: ExamProfile): FamilyRules {
  const base: Record<ExamProfile['family'], FamilyRules> = {
    'sat-style': { choices: 4, multiPartial: false, gridIn: true, roundedOk: false, numberPerSection: true },
    'psat-style': { choices: 4, multiPartial: false, gridIn: true, roundedOk: false, numberPerSection: true },
    'act-style': { choices: 4, multiPartial: false, gridIn: false, roundedOk: true, numberPerSection: false },
    'ap-style': { choices: 4, multiPartial: false, gridIn: false, roundedOk: true, numberPerSection: true },
    'gre-style': { choices: 5, multiPartial: false, gridIn: false, roundedOk: false, numberPerSection: true },
    'ib-style': { choices: 4, multiPartial: false, gridIn: false, roundedOk: true, numberPerSection: true },
    class: { choices: 4, multiPartial: true, gridIn: false, roundedOk: true, numberPerSection: false },
    custom: { choices: 4, multiPartial: true, gridIn: false, roundedOk: true, numberPerSection: false },
  };
  const r = { ...base[family] };
  // Profiles can state their choice count in an observation ("Answer choices per question: 5.").
  const stated = profile?.observations.map((o) => /answer choices per question:\s*(\d)/i.exec(o)?.[1]).find(Boolean);
  if (stated) r.choices = Number(stated);
  return r;
}

/** Number of questions a student actually answers in a section (one adaptive pool, not both). */
export function sectionCount(s: Section): number {
  return s.adaptive ? s.adaptive.hard.length : s.questionIds.length;
}

/** Structural problems in a profile (empty list = valid). */
export function validateProfile(p: ExamProfile): string[] {
  const problems: string[] = [];
  if (!p.sections.length) problems.push('no sections');
  const ids = new Set<string>();
  for (const s of p.sections) {
    if (ids.has(s.id)) problems.push(`duplicate section id ${s.id}`);
    ids.add(s.id);
    if (s.minutes !== null && !(s.minutes > 0)) problems.push(`${s.id}: bad minutes`);
    if (sectionCount(s) === 0) problems.push(`${s.id}: no questions`);
    if (s.adaptive) {
      if (s.adaptive.easy.length !== s.adaptive.hard.length) problems.push(`${s.id}: adaptive pools differ in size`);
      if (!p.sections.some((x) => x.id === s.adaptive!.after)) problems.push(`${s.id}: adaptive.after ${s.adaptive.after} missing`);
      if (!(s.adaptive.threshold > 0 && s.adaptive.threshold < 1)) problems.push(`${s.id}: threshold out of range`);
    }
    if (s.returnTo) {
      // Only back to an EARLIER part (it must have been handed in), and never with more calculator than this part allows.
      const target = p.sections.findIndex((x) => x.id === s.returnTo!.section);
      if (target < 0 || target >= p.sections.indexOf(s)) problems.push(`${s.id}: returnTo must name an earlier section`);
      if (s.returnTo.calculator && !s.calculator) problems.push(`${s.id}: returnTo can't allow a calculator this section doesn't`);
    }
  }
  const w = p.topics.reduce((a, t) => a + t.weight, 0);
  if (p.topics.length && Math.abs(w - 1) > 0.02) problems.push(`topic weights sum to ${w.toFixed(3)}`);
  const m = Object.values(p.mix).reduce((a: number, b) => a + (b ?? 0), 0);
  if (Math.abs(m - 1) > 0.02) problems.push(`mix sums to ${m.toFixed(3)}`);
  if (p.scoring.kind === 'scaled' && !(p.scoring.min !== undefined && p.scoring.max !== undefined && p.scoring.min < p.scoring.max)) problems.push('scaled scoring needs min < max');
  if ((p.scoring.kind === 'band' || p.scoring.bands) && !p.scoring.bands?.some((b) => b.minPercent === 0)) problems.push('bands need a 0% floor');
  return problems;
}
